1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	const (
16		// upstreamServiceName and upstreamServicePort are the Service of the bench
17		// upstream registry and the port the port-forward reaches.
18		upstreamServiceName = upstreamDeployment
19		upstreamServicePort = 5000
20	
21		// seedListWait bounds the wait for a repository to list what the seed put in
22		// it (H-COMPONENTS), and seedListInterval separates two readings.
23		seedListWait     = 30 * time.Second
24		seedListInterval = 2 * time.Second
25	
26		// seedLoopbackHost is the only host the port-forward may be reached on.
27		seedLoopbackHost = "127.0.0.1"
28	
29		// resetCheck is what a repository that holds more than the data set asks.
30		resetCheck = "run `mise run nexus-bench:reset` to bring the bench back to its initial state"
31	)
32	
33	// SeedDeps are the doors Seed goes through: the cluster (to read the upstream),
34	// the port-forward to the upstream, the image copier, the clock of the bounded
35	// wait and the stored secrets.
36	type SeedDeps struct {
37		Runner    Runner
38		Forwarder PortForwarder
39		Copier    ImageCopier
40		Clock     Clock
41		Store     SecretStore
42	}
43	
44	// SeedResult is what Seed leaves in place: the data set, every digest filled,
45	// PullThrough true exactly for the images now cached in docker-proxy.
46	type SeedResult struct{ Images []DatasetImage }
47	
48	// Seed puts the data set (D-I) in place, in this order: the stored credentials,
49	// the state of the upstream (read only), the OCI layout in a temporary folder,
50	// the port-forward to the upstream and the upstream images, the end of the
51	// port-forward, the docker-hosted images, the pull-through of the PullThrough
52	// images by docker-proxy, and the two listings, which must hold the data set and
53	// nothing else. An image is copied only when the digest read at its destination
54	// differs from the one of the data set, so a second run copies nothing.
55	//
56	// Seed never scales, applies or writes to Nexus, and it never restores a cut
57	// upstream (NX-02b): a cut, missing or starting upstream is a SeedFailed before
58	// the first copy. Docker-proxy is read only for the PullThrough images (F9): a
59	// read of mirror/uncached through it would cache it, and only reset removes
60	// that. Every failure is a *BenchError whose cause stays reachable with
61	// errors.Is and is never printed, but a cancelled context, which is returned
62	// as is. A nil out discards the progress lines ("seed: ...", no password).
63	func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
64		if out == nil {
65			out = io.Discard
66		}
67		if err := ctx.Err(); err != nil {
68			return SeedResult{}, err
69		}
70		admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
71		if err != nil {
72			return SeedResult{}, err
73		}
74		defer c.closeIdle()
75		if err := requireSeedableUpstream(ctx, d.Runner, p); err != nil {
76			return SeedResult{}, err
77		}
78	
79		images := Dataset()
80		s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: images}
81		root, err := os.MkdirTemp("", "nexus-bench-seed-")
82		if err != nil {
83			return SeedResult{}, &BenchError{
84				Kind:  SeedFailed,
85				Cause: "the temporary folder of the seed cannot be created",
86				Check: "check that TMPDIR is a folder this user can write to",
87				Err:   err,
88			}
89		}
90		defer func() { _ = os.RemoveAll(root) }()
91		if err := s.writeLayout(root); err != nil {
92			return SeedResult{}, err
93		}
94		steps := []func() error{
95			s.seedUpstream,
96			s.seedHosted,
97			func() error { return s.pullThrough(root) },
98			func() error { return s.verify(dockerProxyRepository, s.wanted(isPullThrough)) },
99			func() error { return s.verify(dockerHostedRepository, s.wanted(isHosted)) },
100		}
101		for _, step := range steps {
102			if err := step(); err != nil {
103				return SeedResult{}, err
104			}
105		}
106		s.say("the data set is in place: %d images", len(images))
107		return SeedResult{Images: images}, nil
108	}
109	
110	// nexusImageRef is the one place that builds the reference of an image of a
111	// repository of the bench Nexus ("docker-hosted" or "docker-proxy"). Today it is
112	// the path routing on the HTTP NodePort (H-PATH): 127.0.0.1:<HTTPNodePort>/
113	// <repository>/<name>:<tag>. Step 12 settles whether the instance serves it.
114	func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
115		return ImageRef{
116			Transport: "docker",
117			Location:  seedLoopbackHost + ":" + strconv.Itoa(p.HTTPNodePort) + "/" + repository + "/" + img.Name + ":" + img.Tag,
118		}
119	}
120	
121	// upstreamImageRef is the reference of an image in the bench upstream reached
122	// through the port-forward at local ("127.0.0.1:<port>"): <local>/<name>:<tag>.
123	func upstreamImageRef(local string, img DatasetImage) ImageRef {
124		return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
125	}
126	
127	// seedCredentials reads the two accounts of the bench from the store and
128	// returns the admin client of the final listings. Nothing is sent to Nexus.
129	func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
130		c, sec, err := adminFromStore(ctx, baseURL, store)
131		if err != nil {
132			if cerr := ctx.Err(); cerr != nil {
133				return admin, pull, nil, cerr
134			}
135			return admin, pull, nil, err
136		}
137		if sec.PullPassword == "" {
138			return admin, pull, nil, &BenchError{
139				Kind:  ProvisionFailed,
140				Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
141				Check: upCheck,
142				Err:   errors.New("no pull password in the secrets file"),
143			}
144		}
145		return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
146	}
147	
148	// requireSeedableUpstream refuses what the seed cannot fill: an upstream URL the
149	// bench did not deploy (the proxy would not read what the seed pushes), and an
150	// upstream that is missing, cut or still starting. It writes nothing: bringing a
151	// cut upstream back is NX-02b.
152	func requireSeedableUpstream(ctx context.Context, r Runner, p Params) error {
153		if !p.UpstreamIsBench() {
154			return &BenchError{
155				Kind:  SeedFailed,
156				Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy, and the seed pushes to the upstream of the bench only", envUpstreamURL),
157				Check: "unset " + envUpstreamURL + " to use the bench upstream",
158			}
159		}
160		state, err := ReadUpstream(ctx, r, p)
161		if err != nil {
162			return err
163		}
164		switch state {
165		case UpstreamMissing:
166			return &BenchError{
167				Kind:  SeedFailed,
168				Cause: fmt.Sprintf("the upstream %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
169				Check: "run `mise run nexus-bench:up`, which deploys it",
170			}
171		case UpstreamCut:
172			return &BenchError{
173				Kind:  SeedFailed,
174				Cause: "the upstream is cut",
175				Check: "run `mise run nexus-bench:restore-upstream`, then the seed again",
176			}
177		case UpstreamStarting:
178			return &BenchError{
179				Kind:  SeedFailed,
180				Cause: "the upstream is still starting",
181				Check: "wait for its pod to be Ready (" + podsCommand(p) + "), then run the seed again",
182			}
183		}
184		return nil
185	}
186	
187	// seeder is one run of Seed.
188	type seeder struct {
189		ctx     context.Context
190		d       SeedDeps
191		p       Params
192		out     io.Writer
193		c       *client
194		baseURL string
195		admin   Credentials
196		pull    Credentials
197		images  []DatasetImage // Dataset(), digests filled
198		layout  string         // the OCI layout folder
199		refs    []string       // the layout reference of images[i]
200	}
201	
202	func (s *seeder) say(format string, args ...any) {
203		_, _ = fmt.Fprintf(s.out, "seed: "+format+"\n", args...)
204	}
205	
206	// writeLayout writes the data set as an OCI layout under root.
207	func (s *seeder) writeLayout(root string) error {
208		s.layout = filepath.Join(root, "layout")
209		err := os.Mkdir(s.layout, 0o700)
210		if err == nil {
211			s.refs, err = WriteLayout(s.layout, s.images)
212		}
213		if err != nil {
214			return &BenchError{
215				Kind:  SeedFailed,
216				Cause: "the OCI layout of the data set cannot be written",
217				Check: "check that TMPDIR has room and is writable",
218				Err:   err,
219			}
220		}
221		return nil
222	}
223	
224	// source is the layout reference of images[i].
225	func (s *seeder) source(i int) ImageRef {
226		return ImageRef{Transport: "oci", Location: s.layout + ":" + s.refs[i]}
227	}
228	
229	func isPullThrough(img DatasetImage) bool { return img.PullThrough }
230	
231	func isHosted(img DatasetImage) bool { return img.Location == LocationHosted }
232	
233	// wanted lists the images of the data set that keep.
234	func (s *seeder) wanted(keep func(DatasetImage) bool) []DatasetImage {
235		var out []DatasetImage
236		for _, img := range s.images {
237			if keep(img) {
238				out = append(out, img)
239			}
240		}
241		return out
242	}
243	
244	// seedUpstream pushes the upstream images through a port-forward that is always
245	// stopped before it returns.
246	func (s *seeder) seedUpstream() error {
247		local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
248		if err != nil {
249			return s.failure(err, "the port-forward to the upstream")
250		}
251		if stop != nil {
252			defer func() { _ = stop() }()
253		}
254		if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
255			return &BenchError{
256				Kind:  SeedFailed,
257				Cause: "the port-forward to the upstream is not on 127.0.0.1",
258				Check: "the bench pushes to a registry on the loopback only: check the kubectl on PATH",
259			}
260		}
261		for i, img := range s.images {
262			if img.Location != LocationUpstream {
263				continue
264			}
265			if err := s.push(i, upstreamImageRef(local, img), nil, "the upstream"); err != nil {
266				return err
267			}
268		}
269		return nil
270	}
271	
272	// seedHosted pushes the docker-hosted images with the admin account.
273	func (s *seeder) seedHosted() error {
274		for i, img := range s.images {
275			if img.Location != LocationHosted {
276				continue
277			}
278			if err := s.push(i, nexusImageRef(s.p, dockerHostedRepository, img), &s.admin, dockerHostedRepository); err != nil {
279				return err
280			}
281		}
282		return nil
283	}
284	
285	// push copies images[i] from the layout to dst unless dst already holds the
286	// digest of the data set. A proven absence (errImageAbsent) is a copy; any
287	// other failure to read stops the seed.
288	func (s *seeder) push(i int, dst ImageRef, creds *Credentials, where string) error {
289		img := s.images[i]
290		name := img.Name + ":" + img.Tag
291		have, err := s.d.Copier.ManifestDigest(s.ctx, dst, creds)
292		if errors.Is(err, errImageAbsent) {
293			have, err = "", nil
294		}
295		if err != nil {
296			return s.failure(err, "reading "+name+" in "+where)
297		}
298		if have == img.Digest {
299			s.say("%s is already in %s", name, where)
300			return nil
301		}
302		s.say("copying %s to %s", name, where)
303		err = s.d.Copier.Copy(s.ctx, s.source(i), dst, CopyOptions{DestCreds: creds, PreserveDigests: true})
304		if err != nil {
305			return s.failure(err, "copying "+name+" to "+where)
306		}
307		return nil
308	}
309	
310	// pullThrough has docker-proxy pull each PullThrough image from the upstream
311	// with the bench-pull account, into a folder that is thrown away. Only these
312	// images are ever read through the proxy (F9): it caches whatever it serves. An
313	// image the proxy already lists with the right digest is not pulled again.
314	func (s *seeder) pullThrough(root string) error {
315		cached, err := s.c.listComponents(s.ctx, dockerProxyRepository)
316		if err != nil {
317			return s.restFailure(err)
318		}
319		for i, img := range s.images {
320			if !img.PullThrough {
321				continue
322			}
323			name := img.Name + ":" + img.Tag
324			if listed(cached, img) {
325				s.say("%s is already cached by %s", name, dockerProxyRepository)
326				continue
327			}
328			s.say("pulling %s through %s", name, dockerProxyRepository)
329			dst := ImageRef{Transport: "dir", Location: filepath.Join(root, fmt.Sprintf("pull-%02d", i+1))}
330			src := nexusImageRef(s.p, dockerProxyRepository, img)
331			if err := s.d.Copier.Copy(s.ctx, src, dst, CopyOptions{SrcCreds: &s.pull, PreserveDigests: true}); err != nil {
332				return s.failure(err, "pulling "+name+" through "+dockerProxyRepository)
333			}
334		}
335		return nil
336	}
337	
338	// listed reports whether components hold img: its name and tag are enough, a
339	// component the instance lists without a digest counts as present (H-COMPONENTS),
340	// and a digest it does list must be the one of the data set.
341	func listed(components []component, img DatasetImage) bool {
342		for _, comp := range components {
343			if comp.Name == img.Name && comp.Version == img.Tag {
344				return comp.Digest == "" || comp.Digest == img.Digest
345			}
346		}
347		return false
348	}
349	
350	// verify waits, for at most seedListWait, until repo lists every image of want
351	// and nothing else (H-COMPONENTS). A component outside the data set cannot be
352	// waited away: it fails at once and asks for a reset.
353	func (s *seeder) verify(repo string, want []DatasetImage) error {
354		deadline := s.d.Clock.Now().Add(seedListWait)
355		for {
356			comps, err := s.c.listComponents(s.ctx, repo)
357			if err != nil {
358				return s.restFailure(err)
359			}
360			if extra := outside(comps, want); len(extra) > 0 {
361				return &BenchError{
362					Kind:  SeedFailed,
363					Cause: fmt.Sprintf("%s holds images outside the dataset (%s)", repo, strings.Join(extra, ", ")),
364					Check: resetCheck,
365				}
366			}
367			missing := absent(comps, want)
368			if len(missing) == 0 {
369				s.say("%s lists the %d images of the data set", repo, len(want))
370				return nil
371			}
372			if !s.d.Clock.Now().Before(deadline) {
373				return &BenchError{
374					Kind:  SeedFailed,
375					Cause: fmt.Sprintf("%s does not list %s after %s", repo, strings.Join(missing, ", "), seedListWait),
376					Check: "run the seed again, and read the log of the pod if it persists: " + podsCommand(s.p),
377				}
378			}
379			if err := s.d.Clock.Sleep(s.ctx, seedListInterval); err != nil {
380				return err
381			}
382		}
383	}
384	
385	// outside lists the "name:tag" of the components that are not in want.
386	func outside(components []component, want []DatasetImage) []string {
387		var out []string
388		for _, comp := range components {
389			known := false
390			for _, img := range want {
391				known = known || (comp.Name == img.Name && comp.Version == img.Tag)
392			}
393			if !known {
394				out = append(out, comp.Name+":"+comp.Version)
395			}
396		}
397		return out
398	}
399	
400	// absent lists the "name:tag" of the images of want that components do not list
401	// with the right digest.
402	func absent(components []component, want []DatasetImage) []string {
403		var out []string
404		for _, img := range want {
405			if !listed(components, img) {
406				out = append(out, img.Name+":"+img.Tag)
407			}
408		}
409		return out
410	}
411	
412	// failure is the error of a step of a door (copier, forwarder): a cancelled
413	// context is returned as is, a *BenchError keeps its kind and gains the step,
414	// and anything else becomes a *BenchError that keeps the cause for errors.Is
415	// without printing it (the text of a sub-process can carry a credential).
416	func (s *seeder) failure(err error, step string) error {
417		if cerr := s.ctx.Err(); cerr != nil {
418			return cerr
419		}
420		var be *BenchError
421		if errors.As(err, &be) {
422			return &BenchError{Kind: be.Kind, Cause: step + ": " + be.Cause, Check: be.Check, Err: err}
423		}
424		return &BenchError{
425			Kind:  Unclassified,
426			Cause: step + " failed",
427			Check: "run the same command by hand to see what it says",
428			Err:   err,
429		}
430	}
431	
432	// restFailure is the error of a listing of Nexus.
433	func (s *seeder) restFailure(err error) error {
434		if cerr := s.ctx.Err(); cerr != nil {
435			return cerr
436		}
437		return asBenchError(err, s.p, s.baseURL)
438	}
