1	package main
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"reflect"
8	
9		"github.com/anthnel/devdesk/internal/nexusbench"
10	)
11	
12	// render prints the manifests. It builds no dependency: it contacts nothing.
13	func (s *session) render() int {
14		out, err := nexusbench.Render(s.p)
15		if err != nil {
16			return s.fail(err)
17		}
18		if _, err := s.stdout.Write(out); err != nil {
19			return s.fail(err)
20		}
21		return exitOK
22	}
23	
24	// open resolves the secrets path and builds the runner and the store, in that
25	// order, before anything touches the cluster. Both are refused here when they
26	// cannot work: kubectl missing, a secrets path that git does not ignore.
27	func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
28		if s.p.SecretsPath == "" {
29			path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
30			if err != nil {
31				return nil, nil, err
32			}
33			s.p.SecretsPath = path
34		}
35		runner, err := s.d.newRunner(s.p.Context)
36		if err != nil {
37			return nil, nil, err
38		}
39		store, err := s.d.newStore(s.p.SecretsPath)
40		if err != nil {
41			return nil, nil, err
42		}
43		return runner, store, nil
44	}
45	
46	// doors are the two doors the seed goes through besides kubectl: the
47	// port-forward to the upstream and the image copier.
48	type doors struct {
49		forwarder nexusbench.PortForwarder
50		copier    nexusbench.ImageCopier
51	}
52	
53	// openDoors builds the doors of the seed, the forwarder first. They are built
54	// before anything touches the cluster: a host without skopeo is refused here,
55	// not after the deployment.
56	func (s *session) openDoors() (doors, error) {
57		forwarder, err := s.d.newForwarder(s.p.Context)
58		if err != nil {
59			return doors{}, err
60		}
61		copier, err := s.d.newCopier()
62		if err != nil {
63			return doors{}, err
64		}
65		return doors{forwarder: forwarder, copier: copier}, nil
66	}
67	
68	// runSeed runs Seed with a context that ends after Params.Timeout, counted from
69	// now, so that a copy over a port-forward that hangs does not hang the command.
70	// A seed that outlasts it is a failure with its own message; a cancelled run
71	// keeps the plain cancellation.
72	func (s *session) runSeed(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) (nexusbench.SeedResult, error) {
73		ctx, cancel := s.ctx, context.CancelFunc(func() {})
74		if s.p.Timeout > 0 {
75			ctx, cancel = context.WithTimeout(s.ctx, s.p.Timeout)
76		}
77		defer cancel()
78		deps := nexusbench.SeedDeps{Runner: runner, Forwarder: d.forwarder, Copier: d.copier, Clock: s.d.clock, Store: store}
79		res, err := s.d.seed(ctx, deps, s.restURL(), s.p, s.stdout)
80		if err != nil && ctx.Err() != nil && s.ctx.Err() == nil {
81			return nexusbench.SeedResult{}, &nexusbench.BenchError{
82				Kind:  nexusbench.Deadline,
83				Cause: fmt.Sprintf("the seed did not finish within %s", s.p.Timeout),
84				Check: "raise --timeout (NEXUS_BENCH_TIMEOUT) and run nexus-bench seed again: the images already copied are kept",
85				Err:   err,
86			}
87		}
88		return res, err
89	}
90	
91	// up deploys the bench and the upstream, provisions Nexus, seeds the data set
92	// and only then writes the descriptor (D-J). Deploy runs the preflight of up
93	// itself. An upstream URL the bench did not deploy is left alone: nothing is
94	// scaled or seeded, and the data set is described as empty.
95	func (s *session) up() int {
96		runner, store, err := s.open()
97		if err != nil {
98			return s.fail(err)
99		}
100		seeds := s.p.UpstreamIsBench()
101		var d doors
102		if seeds {
103			if d, err = s.openDoors(); err != nil {
104				return s.fail(err)
105			}
106		}
107		s.warnIfClearText()
108		deployed, err := s.d.deploy(s.ctx, runner, s.d.newProber(), s.d.clock, s.p, s.stdout)
109		if err != nil {
110			return s.fail(err)
111		}
112		if seeds {
113			if err := s.d.ensureUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
114				return s.fail(err)
115			}
116		}
117		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
118		if err != nil {
119			return s.fail(err)
120		}
121		var seeded nexusbench.SeedResult
122		if seeds {
123			if seeded, err = s.runSeed(runner, store, d); err != nil {
124				return s.fail(err)
125			}
126		} else {
127			_, _ = fmt.Fprintln(s.stdout, "seed: skipped, NEXUS_BENCH_UPSTREAM_URL points at an upstream the bench did not deploy, so there is nothing to fill")
128		}
129		return s.writeDescriptor(deployed, provisioned, seeded)
130	}
131	
132	// provision provisions a bench that is already running.
133	func (s *session) provision() int {
134		runner, store, err := s.open()
135		if err != nil {
136			return s.fail(err)
137		}
138		s.warnIfClearText()
139		pre, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpProvision)
140		if err != nil {
141			return s.fail(err)
142		}
143		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
144		if err != nil {
145			return s.fail(err)
146		}
147		return s.writeDescriptor(nexusbench.DeployResult{NodeIP: pre.NodeIP}, provisioned, s.keptDataset())
148	}
149	
150	// keptDataset returns the data set of the descriptor on disk when it is the
151	// descriptor of the same bench (namespace, context and upstream URL unchanged):
152	// the data set is fixed in the code, and provision touches neither the images nor
153	// the upstream. For another bench, or none, the data set is empty, and when that
154	// drops a data set the command says so. A descriptor that cannot be read (none,
155	// or schema 1) has nothing to keep.
156	func (s *session) keptDataset() nexusbench.SeedResult {
157		prev, err := nexusbench.LoadDescriptor(s.descriptorPath())
158		if err != nil || len(prev.Dataset) == 0 {
159			return nexusbench.SeedResult{}
160		}
161		if prev.Namespace == s.p.Namespace && prev.KubeContext == s.p.Context && prev.Upstream.URL == s.p.UpstreamURL {
162			images := make([]nexusbench.DatasetImage, 0, len(prev.Dataset))
163			for _, img := range prev.Dataset {
164				images = append(images, nexusbench.DatasetImage{
165					Name: img.Name, Tag: img.Tag, Digest: img.Digest,
166					Location: nexusbench.Location(img.Location), PullThrough: img.CachedInProxy,
167				})
168			}
169			return nexusbench.SeedResult{Images: images}
170		}
171		line := "provision: the descriptor now lists no data set"
172		if s.p.UpstreamIsBench() {
173			line += "; run mise run nexus-bench:seed"
174		}
175		_, _ = fmt.Fprintln(s.stdout, line)
176		return nexusbench.SeedResult{}
177	}
178	
179	// seed puts the data set in a bench that up already provisioned, then writes the
180	// descriptor again. Seed has no data of its own about Nexus: the version, the
181	// edition, the EULA consent and the hosts (and so the URLs that depend on them)
182	// come from the descriptor of the previous run, which is read before anything is
183	// copied. The preflight of a seed does not read the node, so it has no address to
184	// give.
185	func (s *session) seed() int {
186		runner, store, err := s.open()
187		if err != nil {
188			return s.fail(err)
189		}
190		d, err := s.openDoors()
191		if err != nil {
192			return s.fail(err)
193		}
194		s.warnIfClearText()
195		prev, err := s.previousDescriptor()
196		if err != nil {
197			return s.fail(err)
198		}
199		if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpSeed); err != nil {
200			return s.fail(err)
201		}
202		seeded, err := s.runSeed(runner, store, d)
203		if err != nil {
204			return s.fail(err)
205		}
206		provisioned := nexusbench.ProvisionResult{NexusVersion: prev.NexusVersion, Edition: prev.Edition, EULAAccepted: prev.EULAAccepted}
207		return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
208	}
209	
210	// previousDescriptor reads the descriptor of the previous run. Without a readable
211	// descriptor of schema 2 (missing, schema 1, not JSON), or with the descriptor of
212	// another bench (namespace or context), the bench was not provisioned by this
213	// build for these parameters, and the answer is to run up.
214	func (s *session) previousDescriptor() (nexusbench.Descriptor, error) {
215		path := s.descriptorPath()
216		prev, err := nexusbench.LoadDescriptor(path)
217		var be *nexusbench.BenchError
218		switch {
219		case err == nil:
220		case errors.As(err, &be):
221			return prev, err
222		default:
223			return prev, &nexusbench.BenchError{
224				Kind:  nexusbench.Unclassified,
225				Cause: "there is no readable descriptor of a provisioned bench (" + err.Error() + ")",
226				Check: "run `mise run nexus-bench:up` first: the seed completes the descriptor that up writes",
227				Err:   err,
228			}
229		}
230		if prev.Namespace != s.p.Namespace || prev.KubeContext != s.p.Context {
231			return prev, &nexusbench.BenchError{
232				Kind:  nexusbench.Unclassified,
233				Cause: fmt.Sprintf("the descriptor %s describes namespace %q on context %q, not namespace %q on context %q", path, prev.Namespace, prev.KubeContext, s.p.Namespace, s.p.Context),
234				Check: "run `mise run nexus-bench:up` for this bench first: the seed completes the descriptor that up writes",
235			}
236		}
237		return prev, nil
238	}
239	
240	// down deletes the bench namespace. The descriptor is left alone: it is the
241	// versioned description of the bench, not part of one instance.
242	func (s *session) down() int {
243		runner, store, err := s.open()
244		if err != nil {
245			return s.fail(err)
246		}
247		if err := s.d.destroy(s.ctx, runner, s.d.clock, store, s.p, s.stdout); err != nil {
248			return s.fail(err)
249		}
250		return exitOK
251	}
252	
253	// descriptorPath is where the descriptor is read and written.
254	func (s *session) descriptorPath() string {
255		if s.p.DescriptorPath != "" {
256			return s.p.DescriptorPath
257		}
258		return nexusbench.DescriptorPath()
259	}
260	
261	// writeDescriptor writes the descriptor of a bench that was provisioned and, for
262	// up and seed, seeded. It is called after a step that succeeded only: a partial
263	// result is never described.
264	func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult, seeded nexusbench.SeedResult) int {
265		path := s.descriptorPath()
266		if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned, seeded)); err != nil {
267			return s.fail(err)
268		}
269		_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
270		if !describesDefaultBench(s.p) {
271			s.warn("descriptor.json now describes a non-default bench; do not commit it")
272		}
273		return exitOK
274	}
275	
276	// describesDefaultBench tells whether p is the bench the versioned descriptor
277	// describes. The timeouts, the paths and the EULA consent do not change what
278	// the bench is, so they are left out.
279	func describesDefaultBench(p nexusbench.Params) bool {
280		normalize := func(p nexusbench.Params) nexusbench.Params {
281			p.Timeout, p.DeleteTimeout = 0, 0
282			p.SecretsPath, p.DescriptorPath = "", ""
283			p.AcceptEULA = false
284			if len(p.Hosts) == 0 {
285				p.Hosts = nil
286			}
287			return p
288		}
289		return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
290	}
