33	// SeedDeps are the doors Seed goes through: the cluster (to read the upstream),
34	// the port-forward to the upstream, the image copier, the clock of the bounded
35	// wait and the stored secrets.
36	type SeedDeps struct {
37		Runner    Runner
38		Forwarder PortForwarder
39		Copier    ImageCopier
40		Clock     Clock
41		Store     SecretStore
42	}
43	
44	// SeedResult is what Seed leaves in place: the data set, every digest filled,
45	// PullThrough true exactly for the images now cached in docker-proxy.
46	type SeedResult struct{ Images []DatasetImage }
47	
48	// Seed puts the data set (D-I) in place, in this order: the stored credentials,
49	// the state of the upstream (read only), the OCI layout in a temporary folder,
50	// the port-forward to the upstream and the upstream images, the end of the
51	// port-forward, the docker-hosted images, the pull-through of the PullThrough
52	// images by docker-proxy, and the two listings, which must hold the data set and
53	// nothing else. An image is copied only when the digest read at its destination
54	// differs from the one of the data set, so a second run copies nothing.
55	//
56	// Seed never scales, applies or writes to Nexus, and it never restores a cut
57	// upstream (NX-02b): a cut, missing or starting upstream is a SeedFailed before
58	// the first copy. Docker-proxy is read only for the PullThrough images (F9): a
59	// read of mirror/uncached through it would cache it, and only reset removes
60	// that. Every failure is a *BenchError whose cause stays reachable with
61	// errors.Is and is never printed, but a cancelled context, which is returned
62	// as is. A nil out discards the progress lines ("seed: ...", no password).
63	func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
64		if out == nil {
65			out = io.Discard
66		}
67		if err := ctx.Err(); err != nil {
68			return SeedResult{}, err
69		}
70		admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
71		if err != nil {
72			return SeedResult{}, err
73		}
74		defer c.closeIdle()
75		if err := requireSeedableUpstream(ctx, d.Runner, p); err != nil {
76			return SeedResult{}, err
77		}
78	
79		images := Dataset()
80		s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: images}
81		root, err := os.MkdirTemp("", "nexus-bench-seed-")
82		if err != nil {
83			return SeedResult{}, &BenchError{
84				Kind:  SeedFailed,
85				Cause: "the temporary folder of the seed cannot be created",
86				Check: "check that TMPDIR is a folder this user can write to",
87				Err:   err,
88			}
89		}
90		defer func() { _ = os.RemoveAll(root) }()
91		if err := s.writeLayout(root); err != nil {
92			return SeedResult{}, err
93		}
94		steps := []func() error{
95			s.seedUpstream,
96			s.seedHosted,
97			func() error { return s.pullThrough(root) },
98			func() error { return s.verify(dockerProxyRepository, s.wanted(isPullThrough)) },
99			func() error { return s.verify(dockerHostedRepository, s.wanted(isHosted)) },
100		}
101		for _, step := range steps {
102			if err := step(); err != nil {
103				return SeedResult{}, err
104			}
105		}
106		s.say("the data set is in place: %d images", len(images))
107		return SeedResult{Images: images}, nil
108	}
109	
110	// nexusImageRef is the one place that builds the reference of an image of a
111	// repository of the bench Nexus ("docker-hosted" or "docker-proxy"). Today it is
112	// the path routing on the HTTP NodePort (H-PATH): 127.0.0.1:<HTTPNodePort>/
113	// <repository>/<name>:<tag>. Step 12 settles whether the instance serves it.
114	func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
115		return ImageRef{
116			Transport: "docker",
117			Location:  seedLoopbackHost + ":" + strconv.Itoa(p.HTTPNodePort) + "/" + repository + "/" + img.Name + ":" + img.Tag,
118		}
119	}
120	
121	// upstreamImageRef is the reference of an image in the bench upstream reached
122	// through the port-forward at local ("127.0.0.1:<port>"): <local>/<name>:<tag>.
123	func upstreamImageRef(local string, img DatasetImage) ImageRef {
124		return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
125	}
126	
127	// seedCredentials reads the two accounts of the bench from the store and
128	// returns the admin client of the final listings. Nothing is sent to Nexus.
129	func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
130		c, sec, err := adminFromStore(ctx, baseURL, store)
131		if err != nil {
132			if cerr := ctx.Err(); cerr != nil {
133				return admin, pull, nil, cerr
134			}
135			return admin, pull, nil, err
136		}
137		if sec.PullPassword == "" {
138			return admin, pull, nil, &BenchError{
139				Kind:  ProvisionFailed,
140				Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
141				Check: upCheck,
142				Err:   errors.New("no pull password in the secrets file"),
143			}
144		}
145		return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
146	}
147	
148	// requireSeedableUpstream refuses what the seed cannot fill: an upstream URL the
149	// bench did not deploy (the proxy would not read what the seed pushes), and an
150	// upstream that is missing, cut or still starting. It writes nothing: bringing a
151	// cut upstream back is NX-02b.
152	func requireSeedableUpstream(ctx context.Context, r Runner, p Params) error {
153		if !p.UpstreamIsBench() {
154			return &BenchError{
155				Kind:  SeedFailed,
156				Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy, and the seed pushes to the upstream of the bench only", envUpstreamURL),
157				Check: "unset " + envUpstreamURL + " to use the bench upstream",
158			}
159		}
160		state, err := ReadUpstream(ctx, r, p)
161		if err != nil {
162			return err
163		}
164		switch state {
165		case UpstreamMissing:
166			return &BenchError{
167				Kind:  SeedFailed,
168				Cause: fmt.Sprintf("the upstream %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
169				Check: "run `mise run nexus-bench:up`, which deploys it",
170			}
171		case UpstreamCut:
172			return &BenchError{
173				Kind:  SeedFailed,
174				Cause: "the upstream is cut",
175				Check: "run `mise run nexus-bench:restore-upstream`, then the seed again",
176			}
177		case UpstreamStarting:
178			return &BenchError{
179				Kind:  SeedFailed,
180				Cause: "the upstream is still starting",
181				Check: "wait for its pod to be Ready (" + podsCommand(p) + "), then run the seed again",
182			}
183		}
184		return nil
185	}
