244	// seedUpstream pushes the upstream images through a port-forward that is always
245	// stopped before it returns.
246	func (s *seeder) seedUpstream() error {
247		local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
248		if err != nil {
249			return s.failure(err, "the port-forward to the upstream")
250		}
251		if stop != nil {
252			defer func() { _ = stop() }()
253		}
254		if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
255			return &BenchError{
256				Kind:  SeedFailed,
257				Cause: "the port-forward to the upstream is not on 127.0.0.1",
258				Check: "the bench pushes to a registry on the loopback only: check the kubectl on PATH",
259			}
260		}
261		for i, img := range s.images {
262			if img.Location != LocationUpstream {
263				continue
264			}
265			if err := s.push(i, upstreamImageRef(local, img), nil, "the upstream"); err != nil {
266				return err
267			}
268		}
269		return nil
270	}
271	
272	// seedHosted pushes the docker-hosted images with the admin account.
273	func (s *seeder) seedHosted() error {
274		for i, img := range s.images {
275			if img.Location != LocationHosted {
276				continue
277			}
278			if err := s.push(i, nexusImageRef(s.p, dockerHostedRepository, img), &s.admin, dockerHostedRepository); err != nil {
279				return err
280			}
281		}
282		return nil
283	}
