1	package main
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	
11		"github.com/anthnel/devdesk/internal/nexusbench"
12	)
13	
14	// listedImage is one image tag a repository lists, as the REST API of Nexus
15	// reports it: the name, the tag and the manifest digest ("sha256:<hex>", empty
16	// when the instance lists none).
17	type listedImage = nexusbench.ListedImage
18	
19	// readImagesAnonymously lists the images of a repository without sending any
20	// credential: a read of what anonymous access allows, nothing else.
21	func readImagesAnonymously(ctx context.Context, baseURL, repository string) ([]listedImage, error) {
22		return nexusbench.ListImagesAnonymously(ctx, baseURL, repository)
23	}
24	
25	// nexusPodSelector is the label of the Nexus pod (see 20-deployment.yaml.tmpl).
26	const nexusPodSelector = "app.kubernetes.io/name=nexus"
27	
28	// status reads the cluster and the descriptor and reports; it changes nothing.
29	// A pod that is missing or a Nexus that does not answer is a finding, not a
30	// failure: the exit code is 1 only when the cluster cannot be read at all.
31	func (s *session) status() int {
32		runner, err := s.d.newRunner(s.p.Context)
33		if err != nil {
34			return s.fail(err)
35		}
36		if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpStatus); err != nil {
37			return s.fail(err)
38		}
39		pod := readPod(s, runner)
40		if err := s.ctx.Err(); err != nil {
41			return s.fail(err)
42		}
43		base := s.restURL()
44		rest := "ready"
45		if err := s.d.newProber().Ready(s.ctx, base); err != nil {
46			// The error is not shown: the text of a failed call is not trusted.
47			rest = "not ready"
48		}
49		if err := s.ctx.Err(); err != nil {
50			return s.fail(err)
51		}
52		upstream := s.describeUpstream(runner)
53		if err := s.ctx.Err(); err != nil {
54			return s.fail(err)
55		}
56		path := s.descriptorPath()
57		desc, descErr := nexusbench.LoadDescriptor(path)
58		dataset := s.describeDataset(desc, descErr, base, rest == "ready")
59		if err := s.ctx.Err(); err != nil {
60			return s.fail(err)
61		}
62		_, _ = fmt.Fprintf(s.stdout, "bench: namespace %s, context %s\n", s.p.Namespace, s.p.Context)
63		_, _ = fmt.Fprintf(s.stdout, "pod: %s\n", pod)
64		_, _ = fmt.Fprintf(s.stdout, "rest: %s (%s)\n", rest, base)
65		_, _ = fmt.Fprintf(s.stdout, "upstream: %s\n", upstream)
66		_, _ = fmt.Fprintf(s.stdout, "descriptor: %s\n", describeDescriptor(path, desc, descErr, s.p))
67		_, _ = fmt.Fprintf(s.stdout, "dataset: %s\n", dataset)
68		return exitOK
69	}
70	
71	// describeUpstream says what the cluster holds of the bench upstream. An
72	// upstream the bench did not deploy is not its to read; a deployment that
73	// cannot be read is a finding, never an error text (it can carry output of
74	// kubectl).
75	func (s *session) describeUpstream(r nexusbench.Runner) string {
76		if !s.p.UpstreamIsBench() {
77			return "not managed by the bench (NEXUS_BENCH_UPSTREAM_URL points elsewhere)"
78		}
79		state, err := s.d.readUpstream(s.ctx, r, s.p)
80		if err != nil {
81			return "unknown (the deployment " + upstreamName + " could not be read)"
82		}
83		switch state {
84		case nexusbench.UpstreamReady:
85			return "ready"
86		case nexusbench.UpstreamCut:
87			return "cut (0 replicas)"
88		case nexusbench.UpstreamStarting:
89			return "starting (no pod is ready yet)"
90		}
91		return "missing (run mise run nexus-bench:up)"
92	}
93	
94	// upstreamName is the Deployment of the bench upstream.
95	const upstreamName = "bench-upstream"
96	
97	// The two repositories that hold the data set. The group is never read: a read
98	// through it can cache an image (F9).
99	const (
100		hostedRepository = "docker-hosted"
101		proxyRepository  = "docker-proxy"
102	)
103	
104	// describeDataset compares the data set the descriptor lists with what
105	// docker-hosted and docker-proxy list now. The listings are anonymous and read
106	// only, so what status cannot read is "unknown", never a failure.
107	func (s *session) describeDataset(d nexusbench.Descriptor, descErr error, base string, restReady bool) string {
108		switch {
109		case descErr != nil:
110			return "unknown (no readable descriptor to compare with)"
111		case len(d.Dataset) == 0 && !s.p.UpstreamIsBench():
112			// seed refuses an upstream the bench did not deploy: no point sending there.
113			return "unknown (the descriptor lists no data set)"
114		case len(d.Dataset) == 0:
115			return "unknown (the descriptor lists no data set: run mise run nexus-bench:seed)"
116		case !restReady:
117			return "unknown (Nexus does not answer)"
118		case !s.p.Anonymous:
119			return "unknown (anonymous access is off and status sends no credential)"
120		}
121		var diffs, compared int
122		for _, repo := range []string{hostedRepository, proxyRepository} {
123			listed, err := s.d.readImages(s.ctx, base, repo)
124			if err != nil {
125				return "unknown (the listing of " + repo + " failed)"
126			}
127			want := expectedIn(d.Dataset, repo)
128			compared += len(want)
129			n, ok := compareListing(want, listed)
130			if !ok {
131				return "unknown (the listing of " + repo + " gives no digest)"
132			}
133			diffs += n
134		}
135		if diffs == 0 {
136			return fmt.Sprintf("matches (%d images compared)", compared)
137		}
138		noun := "images"
139		if diffs == 1 {
140			noun = "image"
141		}
142		return fmt.Sprintf("differs (%d %s)", diffs, noun)
143	}
144	
145	// expectedIn returns the images of the data set that repo holds: the hosted
146	// ones in docker-hosted, the ones cached in the proxy in docker-proxy.
147	func expectedIn(images []nexusbench.DescriptorImage, repo string) []nexusbench.DescriptorImage {
148		var out []nexusbench.DescriptorImage
149		for _, img := range images {
150			if (repo == hostedRepository && img.Location == string(nexusbench.LocationHosted)) ||
151				(repo == proxyRepository && img.CachedInProxy) {
152				out = append(out, img)
153			}
154		}
155		return out
156	}
157	
158	// compareListing counts the differences between what a repository should hold
159	// and what it lists: an image that is missing or has another digest, and an
160	// image the data set does not know. ok is false when the listing gives no
161	// digest for an image that is there, which makes the comparison impossible.
162	func compareListing(want []nexusbench.DescriptorImage, listed []listedImage) (diffs int, ok bool) {
163		have := make(map[string]string, len(listed))
164		for _, img := range listed {
165			have[img.Name+":"+img.Tag] = img.Digest
166		}
167		for _, img := range want {
168			key := img.Name + ":" + img.Tag
169			digest, found := have[key]
170			delete(have, key)
171			switch {
172			case !found:
173				diffs++
174			case digest == "":
175				return 0, false
176			case digest != img.Digest:
177				diffs++
178			}
179		}
180		return diffs + len(have), true
181	}
182	
183	// podList is the part of `kubectl get pods -o json` the report reads.
184	type podList struct {
185		Items []struct {
186			Metadata struct {
187				Name              string `json:"name"`
188				DeletionTimestamp string `json:"deletionTimestamp"`
189			} `json:"metadata"`
190			Status struct {
191				Phase             string `json:"phase"`
192				ContainerStatuses []struct {
193					Ready        bool `json:"ready"`
194					RestartCount int  `json:"restartCount"`
195				} `json:"containerStatuses"`
196			} `json:"status"`
197		} `json:"items"`
198	}
199	
200	// readPod describes the Nexus pod in one line: its phase, name, readiness and restarts.
201	func readPod(s *session, r nexusbench.Runner) string {
202		stdout, _, err := r.Run(s.ctx, nil, "get", "pods", "-n", s.p.Namespace, "-l", nexusPodSelector, "-o", "json", "--request-timeout=10s")
203		if err != nil {
204			return "unknown (kubectl get pods failed)"
205		}
206		var list podList
207		if err := json.Unmarshal(stdout, &list); err != nil {
208			return "unknown (kubectl get pods returned something unreadable)"
209		}
210		if len(list.Items) == 0 {
211			return "not found"
212		}
213		item := list.Items[0]
214		phase := strings.ToLower(item.Status.Phase)
215		if item.Metadata.DeletionTimestamp != "" {
216			phase = "terminating"
217		}
218		if phase == "" {
219			phase = "unknown"
220		}
221		ready, restarts := 0, 0
222		for _, c := range item.Status.ContainerStatuses {
223			if c.Ready {
224				ready++
225			}
226			restarts += c.RestartCount
227		}
228		line := fmt.Sprintf("%s (%s, %d/%d ready, %d restarts", phase, item.Metadata.Name, ready, len(item.Status.ContainerStatuses), restarts)
229		if len(list.Items) > 1 {
230			line += fmt.Sprintf(", %d more pods", len(list.Items)-1)
231		}
232		return line + ")"
233	}
234	
235	// describeDescriptor compares the versioned descriptor, as read at path, with
236	// the parameters of this run and says where they differ.
237	func describeDescriptor(path string, d nexusbench.Descriptor, err error, p nexusbench.Params) string {
238		switch {
239		case errors.Is(err, nexusbench.ErrNoDescriptor):
240			return "not found (" + path + ")"
241		case err != nil:
242			return "unreadable (" + err.Error() + ")"
243		}
244		diffs := descriptorDiffs(d, p)
245		if len(diffs) == 0 {
