11	const (
12		// componentsPath lists the components of a repository.
13		componentsPath = restAPI + "/components"
14		// maxComponentPages bounds a listing: a continuation token that never ends
15		// is an error after this many calls, not an endless loop.
16		maxComponentPages = 1000
17		// manifestMarker is what the path of a Docker manifest asset holds:
18		// v2/<name>/manifests/<tag>.
19		manifestMarker = "/manifests/"
20	
21		// upCheck is what a missing admin password asks the operator to do.
22		upCheck = "run `mise run nexus-bench:up` to provision the bench"
23	)
