25	// component is one image tag a repository lists: the image name, the tag and,
26	// when the instance lists it, the digest of the manifest ("sha256:<hex>").
27	type component struct {
28		Name    string
29		Version string
30		Digest  string
31	}
32	
33	// ListedImage is one image tag a repository lists: the name, the tag and the
34	// manifest digest ("sha256:<hex>", empty when the instance lists none).
35	type ListedImage struct{ Name, Tag, Digest string }
36	
37	// ListImagesAnonymously lists the images of repo on the instance at baseURL
38	// with no credential at all: it is a read of what anonymous access allows, and
39	// a 401 or 403 is an *APIError like any other refusal. It is the listing of the
40	// status command, which never reads docker-group (F9) and never starts skopeo.
41	func ListImagesAnonymously(ctx context.Context, baseURL, repo string) ([]ListedImage, error) {
42		c := newClient(baseURL, "", "")
43		defer c.closeIdle()
44		list, err := c.listComponents(ctx, repo)
45		if err != nil {
46			return nil, err
47		}
