55	// adminFromStore returns a client authenticated with the stored admin password
56	// and the stored secrets. It never reads the initial password of the pod: seed,
57	// restore and reset need a bench that up already provisioned. It sends no
58	// request, so a stored password the instance refuses shows on the first call.
59	func adminFromStore(ctx context.Context, baseURL string, store SecretStore) (*client, Secrets, error) {
60		if err := ctx.Err(); err != nil {
61			return nil, Secrets{}, &transportError{Op: "read the stored admin password", Err: err}
62		}
63		sec, found, err := store.Load()
64		if err != nil {
65			return nil, Secrets{}, &BenchError{
66				Kind:  ProvisionFailed,
67				Cause: "the secrets file of the bench cannot be read",
68				Check: "check the permissions and the content of the secrets file, then " + upCheck,
69				Err:   err,
70			}
71		}
