83	// componentPage is one page of GET /v1/components.
84	type componentPage struct {
85		Items             []componentItem `json:"items"`
86		ContinuationToken *string         `json:"continuationToken"`
87	}
88	
89	type componentItem struct {
90		Name    string           `json:"name"`
91		Version string           `json:"version"`
92		Assets  []componentAsset `json:"assets"`
93	}
94	
95	type componentAsset struct {
96		Path     string `json:"path"`
97		Checksum struct {
98			SHA256 string `json:"sha256"`
99		} `json:"checksum"`
100	}
101	
102	// listComponents lists the components of repo, following the continuation token
103	// until the last page; a token equal to the previous one is an error. A
104	// repository the instance does not know lists as no component. An error on any
105	// page drops what the earlier pages returned.
106	//
107	// H-COMPONENTS (to settle at step 12): a Docker component is one image tag, and
108	// the sha256 checksum of its asset under v2/<name>/manifests/<tag> is the digest
109	// of the manifest.
110	func (c *client) listComponents(ctx context.Context, repo string) ([]component, error) {
111		op := "list the components of " + repo
112		var out []component
113		token := ""
114		for page := 0; page < maxComponentPages; page++ {
115			query := url.Values{"repository": {repo}}
116			if token != "" {
117				query.Set("continuationToken", token)
118			}
119			var body componentPage
120			found, err := c.get(ctx, op, componentsPath, query, &body)
121			if err != nil {
122				return nil, err
123			}
124			if !found {
125				if page == 0 {
126					return nil, nil
127				}
128				return nil, &APIError{Op: op, Status: http.StatusNotFound}
129			}
130			for _, item := range body.Items {
131				out = append(out, component{Name: item.Name, Version: item.Version, Digest: manifestDigest(item)})
132			}
133			if body.ContinuationToken == nil || *body.ContinuationToken == "" {
134				return out, nil
135			}
136			// The same token as the previous page would repeat that page for ever.
137			if *body.ContinuationToken == token {
138				return nil, &decodeError{Op: op, Err: errors.New("the continuation token repeats")}
139			}
140			token = *body.ContinuationToken
141		}
142		return nil, &decodeError{Op: op, Err: errors.New("the continuation token never ends")}
143	}
144	
145	// manifestDigest returns "sha256:<hex>" of the manifest asset of item, or "" when
146	// the instance lists none. The asset of the tag itself wins over any other
147	// manifest asset (a digest-addressed one, for instance).
148	func manifestDigest(item componentItem) string {
149		digest := ""
150		for _, a := range item.Assets {
151			if a.Checksum.SHA256 == "" || !strings.Contains(a.Path, manifestMarker) {
152				continue
153			}
154			if strings.HasSuffix(a.Path, manifestMarker+item.Version) {
155				return "sha256:" + a.Checksum.SHA256
156			}
157			if digest == "" {
158				digest = "sha256:" + a.Checksum.SHA256
159			}
160		}
161		return digest
162	}
