241		case err != nil:
242			return "unreadable (" + err.Error() + ")"
243		}
244		diffs := descriptorDiffs(d, p)
245		if len(diffs) == 0 {
246			return "matches (" + path + ")"
247		}
248		return "differs from the current parameters (" + path + ")\n  " + strings.Join(diffs, "\n  ")
249	}
