145		}
146		resp, err := c.http.Do(req)
147		if err != nil {
148			return response{}, &transportError{Op: r.op, Err: err}
149		}
150		defer func() { _ = resp.Body.Close() }()
151		if resp.StatusCode < 200 || resp.StatusCode > 299 {
152			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
